    v: ["la rosa=la rosa", "el llibre=el libro", "el regal=el regalo", "regalar=regalar", "el drac=el dragón", "la princesa=la princesa", "la llegenda=la leyenda", "signar=firmar", "la parada=el puesto (de venta)", "el punt de llibre=el marcapáginas"],
